import os

import yaml
from launch import LaunchDescription
from launch_ros.actions import Node

THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(THIS_DIR)


def load_file(relative_path):
    with open(os.path.join(BASE_DIR, relative_path), "r") as f:
        return f.read()


def load_yaml(relative_path):
    with open(os.path.join(BASE_DIR, relative_path), "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    robot_description = {"robot_description": load_file("urdf/arm.urdf")}
    robot_description_semantic = {
        "robot_description_semantic": load_file("srdf/arm.srdf")
    }
    robot_description_kinematics = {
        "robot_description_kinematics": load_yaml("config/kinematics.yaml")
    }
    robot_description_planning = {
        "robot_description_planning": load_yaml("config/joint_limits.yaml")
    }

    ompl_planning_yaml = load_yaml("config/ompl_planning.yaml")
    planning_pipelines_config = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_planning_yaml,
    }

    moveit_controllers = load_yaml("config/moveit_controllers.yaml")
    moveit_controllers["moveit_manage_controllers"] = True

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    ros2_controllers_path = os.path.join(BASE_DIR, "config", "ros2_controllers.yaml")

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description],
    )

    ros2_control_node = Node(
        package="controller_manager",
        executable="ros2_control_node",
        parameters=[robot_description, ros2_controllers_path],
        output="screen",
    )

    joint_state_broadcaster_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=[
            "joint_state_broadcaster",
            "--controller-manager-timeout",
            "60",
        ],
        output="screen",
    )

    arm_controller_spawner = Node(
        package="controller_manager",
        executable="spawner",
        arguments=[
            "arm_controller",
            "--controller-manager-timeout",
            "60",
        ],
        output="screen",
    )

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            robot_description_kinematics,
            robot_description_planning,
            planning_pipelines_config,
            moveit_controllers,
            planning_scene_monitor_parameters,
            {"use_sim_time": False},
        ],
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            ros2_control_node,
            joint_state_broadcaster_spawner,
            arm_controller_spawner,
            move_group_node,
        ]
    )

